    const active = this._nativeMediaRescanFlights.get(key);
    if (
      active?.overlay === overlay &&
      active.canvas === canvas &&
      active.workflow === workflow
    ) {
      console.log("[WorkflowRescan] joined native lookup already in progress");
      return active.promise;
    }
    const flight = {
      overlay,
      canvas,
      workflow,
      promise: this._performMediaRescanNow(options),
    };
    this._nativeMediaRescanFlights.set(key, flight);
