  _bindTemplateRefImagesEvents(
    btnId,
    inputId,
    previewId,
    maxImages = 10,
    allowVideo = false,
  ) {
    const owner = this._captureNodeFormPickerOwner();
    const addBtn = this.overlay?.querySelector(`#${btnId}`);
    const hiddenInput = this.overlay?.querySelector(`#${inputId}`);
    const previewContainer = this.overlay?.querySelector(`#${previewId}`);
    if (!addBtn || !hiddenInput) return;
    if (previewContainer) previewContainer.dataset.refOrderInputId = inputId;
    const getUrls = () => {
      try {
        return JSON.parse(hiddenInput.value || "[]");
      } catch (e) {
        return [];
      }
    };
    const saveUrls = (urls) => {
      hiddenInput.value = JSON.stringify(urls);
      if (urls.length === 0) {
        hiddenInput.dataset.cleared = "true";
      } else {
        delete hiddenInput.dataset.cleared;
      }
      this._renderTemplateRefImagesPreview(urls, `#${previewId}`);
    };
    addBtn.addEventListener("click", () => {
      const resolvedMaxImages =
        typeof maxImages === "function"
          ? Number(maxImages())
          : Number(maxImages);
      if (!Number.isFinite(resolvedMaxImages) || resolvedMaxImages < 1) return;
      const currentUrls = getUrls();
      const remaining = resolvedMaxImages - currentUrls.length;
      if (remaining <= 0) {
        window.customDialog?.alert(
          window.I18n?.t("workflow.maxRefImagesReached", {
            max: resolvedMaxImages,
          }) || `Reached limit of ${resolvedMaxImages} reference images.`,
          {
            title: window.I18n?.t("workflow.limitReached") || "Limit reached",
            type: "warning",
          },
        );
        return;
      }
      if (typeof WorkflowMediaModal !== "undefined") {
        const currentUrls2 = getUrls();
        WorkflowMediaModal.show({
          type: "ref_image",
          multiple: true,
          preselected: currentUrls2,
          allowVideo,
          uploadEndpoint: this.isCreatorTemplate
            ? "creator-templates/media"
            : void 0,
          listEndpoint: this.isCreatorTemplate
            ? "creator-templates/media/list"
            : void 0,
          onSelect: (urls) => {
            if (!this._isNodeFormPickerOwnerCurrent(owner)) return;
            const selectedUrls = Array.isArray(urls) ? urls : [urls];
            saveUrls(selectedUrls.slice(0, resolvedMaxImages));
            this._hasUnsavedChanges = true;
          },
        });
      } else {
        console.error(
          "[WorkflowEditor] WorkflowMediaModal kh\xF4ng t\u1ED3n t\u1EA1i",
        );
      }
    });
    if (previewContainer && !previewContainer._templateRefDelegated) {
      previewContainer._templateRefDelegated = true;
      previewContainer.addEventListener("click", (e) => {
        const removeBtn = e.target.closest(".template-ref-thumb-remove");
        if (!removeBtn) return;
        e.stopPropagation();
        e.preventDefault();
        const thumb = removeBtn.closest(".template-ref-thumb");
        const urlToRemove = thumb?.dataset.refUrl;
        if (urlToRemove) {
          const currentUrls = getUrls();
          const filteredUrls = currentUrls.filter((u) => u !== urlToRemove);
          saveUrls(filteredUrls);
          this._hasUnsavedChanges = true;
        }
      });
    }
    const initialUrls = getUrls();
    console.log(
      "[WorkflowEditor] _bindTemplateRefImagesEvents - initialUrls:",
      initialUrls,
      "previewId:",
      previewId,
    );
    this._renderTemplateRefImagesPreview(initialUrls, `#${previewId}`);
  }
