  _resolveRatioClass(ratio) {
    const r = String(ratio || "")
      .trim()
      .toLowerCase();
    if (r === "9:16" || r === "d\u1ECDc" || r === "doc" || r === "story")
      return "ratio-9-16";
    if (r === "3:4" || r === "portrait") return "ratio-3-4";
    if (r === "2:3") return "ratio-2-3";
    if (r === "1:1" || r === "vu\xF4ng" || r === "vuong" || r === "square")
      return "ratio-1-1";
    if (r === "4:3" || r === "landscape") return "ratio-4-3";
    if (r === "3:2") return "ratio-3-2";
    if (r === "16:9" || r === "ngang" || r === "widescreen")
      return "ratio-16-9";
    return "ratio-1-1";
  }
