      "geminiNodePromptMode",
      "geminiNodeRefMode",
      "geminiNodeTimeout",
      "museNodePrompt",
      "museNodeMode",
      "museNodeModel",
      "museNodeRatio",
      "museNodeRefFileIds",
      "museNodeRefImgUrls",
      "museResultImgUrl",
      "museNodeAutoDownload",
      "museNodeDeleteAfterGen",
      "museNodeUploadVideoToFlow",
      "museNodePromptMode",
      "museNodeRefMode",
      "generateNodeRefImgUrls",
      "generateResultImgUrl",
      "chatgptImageRefImgUrls",
      "chatgptResultImgUrl",
      "grokNodeRefImgUrls",
      "grokNodeResultImgUrl",
      "geminiNodeRefImgUrls",
      "geminiNodeResultMedia",
      "promptNodeText",
      "promptNodeMultiPrompt",
      "promptNodeUseAi",
      "promptNodeProvider",
